def _month_keys(X):
    """Month label of each row, taken from the 'date' index level."""
    d = pd.DatetimeIndex(X.index.get_level_values('date'))
    return (d.year * 12 + d.month).to_numpy()


class MissingnessFilter(BaseEstimator, TransformerMixin):
    """Drop variables that are missing too often in the *training* rows."""

    def __init__(self, max_missing=0.9):
        self.max_missing = max_missing

    def fit(self, X, y=None):
        self.kept_columns_ = X.columns[X.isna().mean() <= self.max_missing]
        return self

    def transform(self, X):
        return X[self.kept_columns_]

    def get_feature_names_out(self, input_features=None):
        return np.asarray(self.kept_columns_, dtype=object)


class MonthlyCrossSectionalMeanImputer(BaseEstimator, TransformerMixin):
    """Fill missing values with the mean of the *same month's* cross-section.

    fit() stores a fallback mean per variable, from the training rows, for months where no stock has
    the value. A variable that is missing in every training row has no fallback, so it is dropped.
    """

    def fit(self, X, y=None):
        self.fallback_ = X.mean().dropna()
        return self

    def transform(self, X):
        X = X[self.fallback_.index]
        same_month_mean = X.groupby(_month_keys(X)).transform('mean')   # NaN if nobody has it that month
        return X.fillna(same_month_mean).fillna(self.fallback_)

    def get_feature_names_out(self, input_features=None):
        return np.asarray(self.fallback_.index, dtype=object)


class Winsorizer(BaseEstimator, TransformerMixin):
    """Clip each column at quantiles learned from the training rows."""

    def __init__(self, lower=0.0025, upper=0.9975):
        self.lower = lower
        self.upper = upper

    def fit(self, X, y=None):
        A = np.asarray(X, dtype=np.float64)
        self.lower_bounds_, self.upper_bounds_ = np.nanquantile(A, [self.lower, self.upper], axis=0)
        return self

    def transform(self, X):
        return np.clip(np.asarray(X, dtype=np.float64), self.lower_bounds_, self.upper_bounds_)

    def get_feature_names_out(self, input_features=None):
        return input_features

